// Let's create a helper function inside browserjs to get the details pane content
const extractListingDetails = async (index) => {
  return await browserjs(tabId, async (idx) => {
    const btns = Array.from(document.querySelectorAll('button')).filter(b => b.textContent.trim() === 'Details');
    if (!btns[idx]) return { error: `Button ${idx} not found` };

    btns[idx].click();

    // wait for details pane to load/open
    await new Promise(r => setTimeout(r, 1000));

    // Find details pane/modal/drawer
    const drawer = document.querySelector('[class*="drawer"], [class*="FacilityDetails"], [class*="facility-details"], [role="dialog"], [class*="FacilityView"]');
    const allText = drawer ? drawer.innerText : document.body.innerText;

    // Also look specifically for sections in the details pane
    return {
      title: btns[idx].closest('[class*="css-"]')?.querySelector('h2')?.innerText,
      drawerFound: !!drawer,
      content: drawer ? drawer.innerText : "No drawer found, body snippet: " + document.body.innerText.slice(0, 1000)
    };
  }, index);
};

