const tabId = 343605502;
const checkRes = await browserjs(tabId, () => {
  const modal = document.querySelector('.chakra-modal__content');
  if (!modal) return "No modal";

  const labels = Array.from(modal.querySelectorAll('label, .chakra-checkbox'));
  let clicked = [];

  for (const label of labels) {
    const text = label.innerText?.trim();
    if (text.includes('Garage - Covered') || text.includes('In & Out Allowed')) {
      const input = label.querySelector('input');
      if (input && !input.checked) {
        input.click();
        clicked.push(text);
      }
    }
  }
  return { clicked };
});
console.log("Checked filters:", checkRes);

await new Promise(r => setTimeout(r, 500));

