  const modal = document.querySelector('.chakra-modal__content');
  const btn = modal.querySelector('footer button') || Array.from(modal.querySelectorAll('button')).find(b => b.textContent.includes('Show') || b.textContent.includes('Results'));
  if (btn) {
    const text = btn.textContent.trim();
    btn.click();
    return "clicked: " + text;
  }
  return "submit button not found";
});
console.log(submitBtnRes);

await new Promise(r => setTimeout(r, 1500));

