const tabId = 343605502;
const results = await browserjs(tabId, () => {
  // Let's find all listing cards
  // SpotHero listings typically have class or structure
  const cards = Array.from(document.querySelectorAll('[data-testid*="spot"], [class*="facility-card"], [class*="spot-card"], [class*="SearchListing"]'))
    .concat(Array.from(document.querySelectorAll('main div')).filter(d => d.innerText && d.innerText.includes('Total') && d.innerText.includes('Book Now')));

  // Let's get distinct cards
  const textBlocks = Array.from(document.querySelectorAll('main [class*="css-"]'))
    .filter(el => el.querySelector('h2') && el.innerText.includes('$'));

  return textBlocks.map(el => ({
