  // Find the details view container
  // SpotHero typically places it in a side container or main content
  const detailsEl = document.querySelector('.SpotDetails-open') || 
                    document.querySelector('[data-testid="SpotDetails"]') ||
                    document.querySelector('[class*="SpotDetails"]');

  if (!detailsEl) return { error: "Details container not found" };

  return {
    text: detailsEl.innerText
  };
});

